      var was=cur;cur=n;save();hint.classList.add("gone");updateNudge();if(typeof updateSide==="function")updateSide();closeBubble();updateExplain();stkTrack(n,was);if(window.__fact&&n===0)window.__fact();setTimeout(maybeAskSupport,2500);if(n===N-1)resetCount();
      label();deferVoice();
