      '<div class="st-hit"></div><div class="st-top"><div class="st-bars">'+bars+'</div><div class="st-hd"><span>'+esc(sh.name)+'</span><button class="st-x" aria-label="Close">&times;</button></div></div>'+
      '<div class="st-ft"><span>'+(stI+1)+' / '+L.length+'</span><button class="st-sh">Share &#8599;</button></div>';
