  var FQ=[["Chalisa means forty.", "The Hanuman Chalisa contains forty main verses, with two opening couplets and one closing couplet.", "f091.webp"], ["Written in Awadhi.", "The Chalisa is traditionally attributed to Goswami Tulsidas and written in a language closely connected to everyday speech in his region.", "f092.webp"], ["A prayer for three gifts.", "Strength, wisdom and knowledge. The prayer brings physical courage and inner understanding together.", "f096.webp"], ["The mind is a mirror.", "The opening uses the image of cleaning a mirror to describe preparing the mind through the guru’s guidance.", "f095.webp"], ["Wisdom comes before strength.", "The first verse calls him an ocean of wisdom and virtue. His immense strength is praised in the next.", "f094.webp"], ["One reading can be your daily prayer.", "The Chalisa does not set a minimum of three, seven or eleven readings. A single attentive recitation can be a meaningful devotional practice.", "f089.webp"], ["Three, seven, eleven: customs vary.", "These counts may be chosen for a personal prayer commitment or followed within a tradition. The Chalisa does not assign a separate, guaranteed benefit to each.", "f108.webp"], ["The hundred recitations.", "Verse 38 associates a hundred readings with freedom from bondage and great happiness. It does not say they must all happen in one sitting.", "f103.webp"], ["Reflect on one verse at a time.", "Each verse offers something to contemplate, from courage to service. Calling every verse a “maha mantra” expresses devotional reverence; it is not a classification given by the Chalisa itself.", "f097.webp"], ["Thought, speech and action.", "Verse 26 connects remembering Hanuman with all three, inviting prayer to influence everyday life.", "f100.webp"], ["It ends with Hanuman in the heart.", "The closing prayer welcomes Hanuman together with Rama, Sita and Lakshmana.", "f106.webp"], ["A fruit as bright as the sun.", "A beloved childhood story describes him reaching for the sun, thinking it was something delicious to eat. The Chalisa recalls this episode.", "f003.webp"], ["Many names, one family.", "Anjaneya refers to his mother Anjana, while Pavanputra means son of the wind. The Chalisa also calls him Kesari’s son.", "f011.webp"], ["He could change his size.", "Sacred stories describe him becoming tiny or enormous as the task required. The Chalisa remembers his different forms.", "f024.webp"], ["Rama’s ring for Sita.", "In the Ramayana, the ring helps Sita recognise him as Rama’s messenger when he finds her in Lanka.", "f038.webp"], ["Across the ocean on a rescue.", "His famous leap to Lanka was part of the search for Sita, a feat of strength in the service of someone else.", "f026.webp"], ["He carried a mountain.", "In the familiar Ramayana account, he brings the mountain when he cannot identify the needed herb, helping save Lakshmana.", "f059.webp"], ["As dear as Bharata.", "The Chalisa recalls Rama telling Hanuman that he is as dear to him as Bharata.", "f066.webp"], ["He brought Rama and Sugriva together.", "He plays an important role in their alliance, showing his ability to build trust as well as overcome obstacles.", "f018.webp"], ["He loves to hear Rama’s story.", "The Chalisa describes his love of listening to Rama’s deeds, with Rama, Sita and Lakshmana living in his heart.", "f079.webp"], ["Power paired with humility.", "The Chalisa celebrates his extraordinary abilities while describing him as Rama’s devoted servant. A lesson we can draw is to use our abilities with care and purpose.", "f021.webp"]],FICO={"book": "<path d=\"M4 5.5A2.5 2.5 0 0 1 6.5 3H20v16H6.5A2.5 2.5 0 0 0 4 21.5z\"/><path d=\"M8 7h8M8 11h6\"/>", "chat": "<path d=\"M21 12a8 8 0 0 1-11.6 7.1L4 20l1-4.6A8 8 0 1 1 21 12z\"/><path d=\"M8.5 11h7M8.5 14h4\"/>", "spark": "<path d=\"M12 3l1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8z\"/><path d=\"M18 16l.8 2.2L21 19l-2.2.8L18 22l-.8-2.2L15 19l2.2-.8z\"/>", "mirror": "<ellipse cx=\"12\" cy=\"9\" rx=\"6\" ry=\"7\"/><path d=\"M12 16v6M9 22h6\"/>", "sun": "<circle cx=\"12\" cy=\"12\" r=\"4.2\"/><path d=\"M12 2.5v3M12 18.5v3M2.5 12h3M18.5 12h3M5.3 5.3l2.1 2.1M16.6 16.6l2.1 2.1M18.7 5.3l-2.1 2.1M7.4 16.6l-2.1 2.1\"/>", "heart": "<path d=\"M12 20s-7-4.6-7-10a4 4 0 0 1 7-2.6A4 4 0 0 1 19 10c0 5.4-7 10-7 10z\"/>", "expand": "<path d=\"M4 20V4M20 20V4M4 12h16M7 9l-3 3 3 3M17 9l3 3-3 3\"/>", "ring": "<circle cx=\"12\" cy=\"14.5\" r=\"6\"/><path d=\"M9.5 7.5L12 3l2.5 4.5\"/>", "wave": "<path d=\"M2 12c2.5-3 4.5-3 7 0s4.5 3 7 0 4.5-3 6 0M2 18c2.5-3 4.5-3 7 0s4.5 3 7 0 4.5-3 6 0\"/><circle cx=\"17\" cy=\"6\" r=\"2.5\"/>", "mountain": "<path d=\"M3 20l6-10 4 6 3-4 5 8z\"/>", "people": "<circle cx=\"8\" cy=\"8\" r=\"3\"/><circle cx=\"16\" cy=\"8\" r=\"3\"/><path d=\"M3 20c0-3 2.5-5 5-5M21 20c0-3-2.5-5-5-5M9 20c0-2 1.5-3 3-3s3 1 3 3\"/>"};
